double doughnut[1 << OBJ_SIZE][3];
double ball0[1 << OBJ_SIZE][3];
double(*objs[])[3] = { stars,doughnut,NULL };

double rot[3][3] = { {1,0,0},{0,1,0},{0,0,1} };
double rot_rot[3][3];
double v[3] = { 0,0,0 };

void rotation(double* v, double(*a)[3], int i,int t)
{
	double r_tmp[3] = { 0 };
	for (int j = 0; j < 3; ++j)
		for (int k = 0; k < 3; ++k)
			if(t)
				r_tmp[j] += a[(k + i) % 3][(j + i) % 3] * v[k];
			else
				r_tmp[j] += a[(j + i) % 3][(k + i) % 3] * v[k];
	for (int j = 0; j < 3; ++j)
		v[j] = r_tmp[j];
}

void init() //initialization
{
	rot_rot[0][0] = 1.0;
	rot_rot[0][1] = 0.0;
	rot_rot[0][2] = 0.0;

	rot_rot[1][0] = 0.0;
	rot_rot[1][1] = cos(ANG_ACCEL);
	rot_rot[1][2] = -sin(ANG_ACCEL);

	rot_rot[2][0] = 0.0;
	rot_rot[2][1] = sin(ANG_ACCEL);
	rot_rot[2][2] = cos(ANG_ACCEL);

	for (int i = 0; i < 1 << OBJ_SIZE; ++i)
	{
		ball0[i][0] = sin((i / (1 << OBJ_SIZE / 2)) * M_2PI / (1 << OBJ_SIZE / 2)) * cos((i % (1 << OBJ_SIZE / 2)) * M_2PI / (1 << OBJ_SIZE / 2));
		ball0[i][1] = sin((i / (1 << OBJ_SIZE / 2)) * M_2PI / (1 << OBJ_SIZE / 2)) * sin((i % (1 << OBJ_SIZE / 2)) * M_2PI / (1 << OBJ_SIZE / 2));
		ball0[i][2] = cos((i / (1 << OBJ_SIZE / 2)) * M_2PI / (1 << OBJ_SIZE / 2));

		doughnut[i][0] = cos(M_2PI * i / (1 << OBJ_SIZE)) * (16 + 8 * cos(M_2PI * i / (1 << OBJ_SIZE / 2 - 1)));
		doughnut[i][1] = sin(M_2PI * i / (1 << OBJ_SIZE)) * (16 + 8 * cos(M_2PI * i / (1 << OBJ_SIZE / 2 - 1)));
		doughnut[i][2] = 8 * sin(M_2PI * i / (1 << OBJ_SIZE / 2 - 1));
	}
}

void draw(void)
{
	for (int i = 0; i < RES_X * RES_Y; ++i)
		char_buff[i] = ' ';
	double(**p_obj)[3] = objs;
	while (*p_obj != NULL)
	{
		double (*p_dot)[3] = *p_obj;
		for (int i = 1 << OBJ_SIZE; i; --i)
		{
			rotation(*p_dot, rot, 0, 0);
			if (*p_obj != stars)
				for (int j = 0; j < 3; ++j)
					(*p_dot)[j] -= v[j];
			if ((*p_dot)[2] > 0 && (*p_obj != ball0 || coordinate))
			{
				int screen_x = (int)(((*p_dot)[0] / (*p_dot)[2] + 1) * RES_X / 2);
				int screen_y = (int)(((*p_dot)[1] / (*p_dot)[2] + 1) * RES_Y / 2);
				if (screen_x >= 0 && screen_x < RES_X&& screen_y >= 0 && screen_y < RES_Y)
					char_buff[screen_x + screen_y * RES_X] = '+';
			}
			++p_dot;
		}
		++p_obj;
	}
}

void display()//main display function; widows-specific
{
	HANDLE hand = GetStdHandle(STD_OUTPUT_HANDLE); //handle to console window
	DWORD written; //helper flag, unused
	WriteConsole(hand, char_buff, RES_X * RES_Y, &written, NULL); //write Gthe character contents of buff[]
}

void controls()//handles keyboard; windows-specific
{
	int keylist1[6] = { 'J','H','G','F','D','S' };
	for (int i = 0; i < 6; ++i)
		if (GetKeyState(keylist1[i]) & 0x8000)
			for (int j = 0; j < 3; ++j)
				rotation(rot[j], rot_rot, i / 2, i % 2);
	rotation(v, rot, 0, 0);
	int keylist2[6] = { 0,0,0,0,'K','L'};
	for (int i = 0; i < 6; ++i)
		if (GetKeyState(keylist2[i]) & 0x8000)
			if (i % 2)
				v[i / 2] += ACCEL;
			else
				v[i / 2] -= ACCEL;
}

int main()
{
	init();
	while (1)
	{
		if (GetKeyState(VK_ESCAPE) & 0x8000)//push ESCAPE to shutdown the app
			return 0;
		if (GetKeyState('C') & 0x8000)//push C to activate or diactivate coodinate
			coordinate=~coordinate;
		controls();
		draw();
		display();
		Sleep(50);
		//do_continue = 0;
	}
}